INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'charity', 'n.', '/ˈtʃærəti/', '慈善机构;慈善团体', 'A local wildlife charity is working to save the rare cranes.', '一个本地野生动物慈善机构正在努力拯救稀有的鹤。', 'Into the Wild', 1, 0, 'senior', 'wordlist', 'required1', 'U5', 'a wildlife charity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'monarch', 'n.', '/ˈmɒnək/', '君主;(monarch butterfly)黑脉金斑蝶', 'The monarch butterfly is famous for its long autumn journey south.', '黑脉金斑蝶以其漫长的秋季南迁而闻名。', 'Into the Wild', 2, 0, 'senior', 'wordlist', 'required1', 'U5', 'the monarch butterfly', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'whale', 'n.', '/weɪl/', '鲸', 'A huge whale rose slowly to the surface near our boat.', '一头巨大的鲸缓缓浮到我们船边的水面上。', 'Into the Wild', 3, 0, 'senior', 'wordlist', 'required1', 'U5', 'a killer whale', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'annual', 'adj.', '/ˈænjuəl/', '一年一度的;每年的', 'Every autumn these birds begin their annual journey to warmer lands.', '每年秋天这些鸟都开始它们一年一度的迁往温暖地区的旅程。', 'Into the Wild', 4, 0, 'senior', 'wordlist', 'required1', 'U5', 'the annual migration', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'migration', 'n.', '/maɪˈɡreɪʃn/', '迁徙;迁移', 'The migration of the monarch butterfly is one of nature''s wonders.', '黑脉金斑蝶的迁徙是大自然的奇迹之一。', 'Into the Wild', 5, 0, 'senior', 'wordlist', 'required1', 'U5', 'animal migration', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'migrate', 'v.', '/maɪˈɡreɪt/', '迁徙;移栖', 'Many animals migrate to find food or warmer weather.', '许多动物迁徙是为了寻找食物或更温暖的天气。', 'Into the Wild', 6, 0, 'senior', 'wordlist', 'required1', 'U5', 'migrate south', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'seek', 'v.', '/siːk/', '寻找;寻求', 'These insects migrate to seek a partner and warmer weather.', '这些昆虫迁徙是为了寻找配偶和更温暖的天气。', 'Into the Wild', 7, 0, 'senior', 'wordlist', 'required1', 'U5', 'seek warmer weather', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'professor', 'n.', '/prəˈfesə/', '教授', 'A professor and his team finally solved the mystery of the butterfly.', '一位教授和他的团队终于解开了这种蝴蝶之谜。', 'Into the Wild', 8, 0, 'senior', 'wordlist', 'required1', 'U5', 'a professor of biology', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'measure', 'v.', '/ˈmeʒə/', '测量;衡量', 'The butterfly uses its eyes to measure the position of the sun.', '这种蝴蝶用眼睛来测量太阳的位置。', 'Into the Wild', 9, 0, 'senior', 'wordlist', 'required1', 'U5', 'measure the position', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'position', 'n.', '/pəˈzɪʃn/', '位置;方位', 'By checking the sun''s position, the bird knows which way to fly.', '通过查看太阳的位置,这只鸟便知道该往哪个方向飞。', 'Into the Wild', 10, 0, 'senior', 'wordlist', 'required1', 'U5', 'the position of the sun', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'determine', 'v.', '/dɪˈtɜːmɪn/', '确定;测定;决定', 'These two clues help the butterfly determine the way to go.', '这两条线索帮助蝴蝶确定前进的方向。', 'Into the Wild', 11, 0, 'senior', 'wordlist', 'required1', 'U5', 'determine the way', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'eventually', 'adv.', '/ɪˈventʃuəli/', '终于;最终', 'Eventually, the monarchs reach the forests where they spend the winter.', '最终,这些黑脉金斑蝶到达它们过冬的森林。', 'Into the Wild', 12, 0, 'senior', 'wordlist', 'required1', 'U5', 'eventually reach', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'solution', 'n.', '/səˈluːʃn/', '解决方法;答案', 'Scientists searched for years before they found the solution to the puzzle.', '科学家们找了多年才找到这个谜题的答案。', 'Into the Wild', 13, 0, 'senior', 'wordlist', 'required1', 'U5', 'find a solution', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'mystery', 'n.', '/ˈmɪstri/', '谜;难以理解的事物', 'How these tiny insects find their way was a mystery for a long time.', '这些小昆虫如何找到路曾长期是个谜。', 'Into the Wild', 14, 0, 'senior', 'wordlist', 'required1', 'U5', 'solve a mystery', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'amazing', 'adj.', '/əˈmeɪzɪŋ/', '惊人的;了不起的', 'The monarch''s amazing ability to navigate surprised everyone.', '黑脉金斑蝶惊人的导航能力让所有人都很吃惊。', 'Into the Wild', 15, 0, 'senior', 'wordlist', 'required1', 'U5', 'an amazing ability', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'crash', 'v.', '/kræʃ/', '暴跌;猛撞', 'The number of these butterflies has crashed in the last few years.', '这些蝴蝶的数量在过去几年里暴跌。', 'Into the Wild', 16, 0, 'senior', 'wordlist', 'required1', 'U5', 'numbers crash', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'destroy', 'v.', '/dɪˈstrɔɪ/', '破坏;毁掉', 'People are destroying the natural environment that wild animals need.', '人们正在破坏野生动物所需要的自然环境。', 'Into the Wild', 17, 0, 'senior', 'wordlist', 'required1', 'U5', 'destroy the environment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'chemical', 'n.', '/ˈkemɪkl/', '化学品', 'Farmers use chemicals that kill the plants the caterpillars eat.', '农民使用的化学品杀死了毛虫所吃的植物。', 'Into the Wild', 18, 0, 'senior', 'wordlist', 'required1', 'U5', 'harmful chemicals', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'creature', 'n.', '/ˈkriːtʃə/', '生物;动物', 'The more we know about this creature, the better we can protect it.', '我们对这种生物了解得越多,就越能保护它。', 'Into the Wild', 19, 0, 'senior', 'wordlist', 'required1', 'U5', 'a lovely creature', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'survive', 'v.', '/səˈvaɪv/', '幸存;活下来', 'With our help, these butterflies have a better chance to survive.', '有了我们的帮助,这些蝴蝶就更有可能存活下来。', 'Into the Wild', 20, 0, 'senior', 'wordlist', 'required1', 'U5', 'survive in the wild', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'effect', 'n.', '/ɪˈfekt/', '影响;结果;效果', 'Cutting down trees has a serious effect on wild animals.', '砍伐树木对野生动物有严重的影响。', 'Into the Wild', 21, 0, 'senior', 'wordlist', 'required1', 'U5', 'a cause-effect chart', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'caterpillar', 'n.', '/ˈkætəpɪlə/', '毛虫(蝴蝶等的幼虫)', 'Each caterpillar must eat a lot of leaves before it becomes a butterfly.', '每条毛虫在变成蝴蝶之前都必须吃很多叶子。', 'Into the Wild', 22, 0, 'senior', 'wordlist', 'required1', 'U5', 'a hungry caterpillar', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'accommodation', 'n.', '/əˌkɒməˈdeɪʃn/', '住处;住宿', 'Our accommodation looked out over a waterhole full of wild animals.', '我们的住处俯瞰一处满是野生动物的水塘。', 'Into the Wild', 23, 0, 'senior', 'wordlist', 'required1', 'U5', 'perfect accommodation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'idiom', 'n.', '/ˈɪdiəm/', '习语;成语', 'Many English idioms use the names of animals, such as ''as busy as a bee''.', '许多英语习语都用到动物的名字,比如"忙得像只蜜蜂"。', 'Into the Wild', 24, 0, 'senior', 'wordlist', 'required1', 'U5', 'animal idioms', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'authority', 'n.', '/ɔːˈθɒrəti/', '当权者;权力;管理机构', 'The local authority has set up a reserve to protect the wild birds.', '当地管理机构设立了一个保护区来保护野生鸟类。', 'Into the Wild', 25, 0, 'senior', 'wordlist', 'required1', 'U5', 'in authority', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'source', 'n.', '/sɔːs/', '来源;源头', 'Wetlands are an important source of food for many wild birds.', '湿地是许多野生鸟类重要的食物来源。', 'Into the Wild', 26, 0, 'senior', 'wordlist', 'required1', 'U5', 'a source of food', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'found', 'v.', '/faʊnd/', '创立;创建', 'The first national park in the world was founded long ago.', '世界上第一个国家公园在很久以前就创立了。', 'Into the Wild', 27, 0, 'senior', 'wordlist', 'required1', 'U5', 'found a park', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'photographer', 'n.', '/fəˈtɒɡrəfə/', '摄影师', 'As a nature photographer, I often work outside in all kinds of weather.', '作为一名自然摄影师,我经常在各种天气下在户外工作。', 'Into the Wild', 28, 0, 'senior', 'wordlist', 'required1', 'U5', 'a nature photographer', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'button', 'n.', '/ˈbʌtn/', '按钮', 'I forced my finger to press the button just before the bear ran away.', '就在那头熊跑开之前,我强迫自己的手指按下了按钮。', 'Into the Wild', 29, 0, 'senior', 'wordlist', 'required1', 'U5', 'press the button', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'recover', 'v.', '/rɪˈkʌvə/', '恢复;康复', 'When I recovered from the shock, I looked down at my camera.', '当我从震惊中恢复过来时,我低头看了看我的相机。', 'Into the Wild', 30, 0, 'senior', 'wordlist', 'required1', 'U5', 'recover from the shock', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'shock', 'n.', '/ʃɒk/', '震惊;吃惊', 'Seeing a bear only metres away gave me a real shock.', '看到一头熊就在几米之外,让我大吃一惊。', 'Into the Wild', 31, 0, 'senior', 'wordlist', 'required1', 'U5', 'recover from the shock', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'element', 'n.', '/ˈelɪmənt/', '要素;(the elements)恶劣天气', 'A wildlife photographer must brave the elements to get a good shot.', '野生动物摄影师必须不顾恶劣天气才能拍到好照片。', 'Into the Wild', 32, 0, 'senior', 'wordlist', 'required1', 'U5', 'brave the elements', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'variety', 'n.', '/vəˈraɪəti/', '多样化;种类', 'The park is famous for the variety of its wildlife.', '这个公园以其野生动物的多样性而闻名。', 'Into the Wild', 33, 0, 'senior', 'wordlist', 'required1', 'U5', 'a variety of wildlife', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'encounter', 'n.', '/ɪnˈkaʊntə/', '意外的相遇;邂逅', 'My encounter with the bear was both frightening and magical.', '我与那头熊的相遇既令人害怕又充满魔力。', 'Into the Wild', 34, 0, 'senior', 'wordlist', 'required1', 'U5', 'an encounter with nature', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'path', 'n.', '/pɑːθ/', '小径;小道', 'I followed a narrow path that led me through a dark forest.', '我沿着一条狭窄的小路穿过一片黑暗的森林。', 'Into the Wild', 35, 0, 'senior', 'wordlist', 'required1', 'U5', 'follow a path', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'breathtaking', 'adj.', '/ˈbreθteɪkɪŋ/', '令人惊叹的;惊人的', 'When I stepped out of the trees, the breathtaking view stopped me.', '当我走出树林时,那令人惊叹的景色让我停下了脚步。', 'Into the Wild', 36, 0, 'senior', 'wordlist', 'required1', 'U5', 'a breathtaking view', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'eagle', 'n.', '/ˈiːɡl/', '鹰;雕', 'An eagle flew high over the snow-capped mountains and the still lake.', '一只鹰在白雪覆盖的群山和平静的湖面上空高高飞过。', 'Into the Wild', 37, 0, 'senior', 'wordlist', 'required1', 'U5', 'a flying eagle', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'concentrate', 'v.', '/ˈkɒnsntreɪt/', '专注;集中(注意力)', 'While I was concentrating on the scene, I felt that I was being watched.', '当我专注于眼前的景色时,我感到自己正被注视着。', 'Into the Wild', 38, 0, 'senior', 'wordlist', 'required1', 'U5', 'concentrate on', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'freeze', 'v.', '/friːz/', '(因恐惧等)呆住;结冰', 'I turned, saw the bear, and froze, unable to move at all.', '我转过身,看见那头熊,然后呆住了,完全动弹不得。', 'Into the Wild', 39, 0, 'senior', 'wordlist', 'required1', 'U5', 'freeze with fear', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stare', 'v.', '/steə/', '凝视;盯着看', 'With water falling off its hair, the bear stared back at me.', '水从它的毛发上滴落,那头熊回瞪着我。', 'Into the Wild', 40, 0, 'senior', 'wordlist', 'required1', 'U5', 'stare back', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'capture', 'v.', '/ˈkæptʃə/', '(用图片或文字)记录;捕捉;俘获', 'My most frightening experience was now captured forever in one image.', '我最惊险的经历如今被永远地记录在一张图片里。', 'Into the Wild', 41, 0, 'senior', 'wordlist', 'required1', 'U5', 'capture a moment', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'image', 'n.', '/ˈɪmɪdʒ/', '图像;影像', 'The whole magical scene was held forever in a single image.', '整个奇妙的场景被永远定格在一张图像里。', 'Into the Wild', 42, 0, 'senior', 'wordlist', 'required1', 'U5', 'a single image', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'reaction', 'n.', '/riˈækʃn/', '反应', 'His calm reaction when he saw the bear surprised the whole class.', '他看到熊时冷静的反应让全班同学都很惊讶。', 'Into the Wild', 43, 0, 'senior', 'wordlist', 'required1', 'U5', 'a quick reaction', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'file', 'n.', '/faɪl/', '档案;文件', 'We made an animal fact file about the red-crowned crane.', '我们做了一份关于丹顶鹤的动物档案。', 'Into the Wild', 44, 0, 'senior', 'wordlist', 'required1', 'U5', 'an animal fact file', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'per cent', 'n.', '/pə ˈsent/', '百分之……', 'The number of monarchs has fallen by as much as ninety per cent.', '黑脉金斑蝶的数量已下降了多达百分之九十。', 'Into the Wild', 45, 0, 'senior', 'wordlist', 'required1', 'U5', 'ninety per cent', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u5.01', '①when(时间先行词 = on/in/at which)', 'A2', 10, '外研社版必修第一册 U5 — 先行词表时间(day/time/year/moment/season 等)、从句不缺主语或宾语(只缺时间状语)时,用关系副词 when(= 介词+which)。', 1, 'required1', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u5.02', '②where(地点先行词 = in/at/on which)', 'A2', 10, '外研社版必修第一册 U5 — 先行词表地点(place/country/forest/lake 等)、从句只缺地点状语时,用关系副词 where(= 介词+which)。', 2, 'required1', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u5.03', '③why(原因)+ 关系副词 vs 关系代词判断', 'A2', 10, '外研社版必修第一册 U5 — 先行词为 reason、从句缺原因状语时用 why;但若从句缺主语/宾语,即使先行词表时间/地点也要用关系代词 that;介词后只能用 which。', 3, 'required1', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.01'), '"I still remember the day ____ I first saw a wild eagle in the mountains."', 'when', 'which', 'where', 'that', 'A', '先行词 day 表时间,从句不缺主宾(只缺时间状语)→ when。', 2, 1, 'mcq');
