INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"Nobody knows the real reason ____ the birds changed their usual path."', 'that', 'which', 'why', 'where', 'C', '先行词 reason → why。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"There must be a reason ____ so many whales come to this bay each year."', 'that', 'which', 'where', 'why', 'D', '先行词 reason → why。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"The day ____ changed my view of wild animals was truly unforgettable."', 'that', 'when', 'where', 'why', 'A', '先行词 day 虽表时间,但从句缺主语 → 用关系代词 that(不是 when)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"The photo ____ I took of the bear later won a national prize."', 'when', 'that', 'where', 'why', 'B', '先行词 photo、从句缺宾语 → 关系代词 that。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"The eagle ____ flew over the lake was the largest I had ever seen."', 'when', 'where', 'that', 'why', 'C', '先行词 eagle、从句缺主语 → that。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"The forest ____ we visited last spring was full of singing birds."', 'when', 'where', 'why', 'that', 'D', '先行词 forest 虽表地点,但从句缺宾语(visited ___)→ 用 that(不是 where)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"The animals ____ live in this park are protected by law."', 'that', 'when', 'where', 'why', 'A', '先行词 animals、从句缺主语 → that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"The first creature ____ I photographed in the wild was a red deer."', 'when', 'that', 'where', 'why', 'B', '先行词 creature、从句缺宾语 → that。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"The river ____ runs through the valley is home to many fish."', 'when', 'where', 'that', 'why', 'C', '先行词 river、从句缺主语 → that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"The path ____ we followed led us deep into the dark forest."', 'when', 'where', 'why', 'that', 'D', '先行词 path 虽表地点,但从句缺宾语(followed ___)→ 用 that(不是 where)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"These are the tall trees on ____ the eagles build their huge nests."', 'which', 'that', 'when', 'where', 'A', '介词 on 后只能用 which(不可 that)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"That is the way in ____ the butterflies find their direction south."', 'that', 'which', 'when', 'where', 'B', 'the way in which;介词 in 后用 which。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"A camera is the tool with ____ this photographer captures wild animals."', 'that', 'when', 'which', 'where', 'C', '介词 with 后指物用 which。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U5' AND code='f1u5.03'), '"Sunlight is the means by ____ green plants make their own food."', 'that', 'when', 'where', 'which', 'D', 'a means by which;介词 by 后用 which。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Monarch''s Journey', 'Every autumn, millions of monarch butterflies with fine black and orange wings begin a long and difficult journey. Somehow they travel around four thousand kilometres south and find their way to California or Mexico. For a long time, no one knew how such tiny insects could do this. Then a team led by a professor at an American university found the answer. The monarch is able to tell the time of day, and it also uses its eyes to check where the sun sits in the sky. These two clues together allow the butterfly to work out the right direction to fly. In the end, it reaches the warm forests where it will spend the cold winter. The discovery is amazing, yet it has come at a worrying time, because the number of monarchs has dropped sharply in recent years.', 'Into the Wild', 140, '[{"q":"What had long puzzled people about the monarch butterfly?","answer":"A","options":["How such a small insect found its way so far.","Why it had black and orange wings.","When it first appeared on the earth.","Where its name came from."],"explanation":"原文 ''no one knew how such tiny insects could do this'' 的转述。"},{"q":"How does the monarch decide which way to fly?","answer":"B","options":["By following other larger birds.","By noting the hour and the sun''s position above.","By smelling the flowers below.","By listening to the wind."],"explanation":"中段 ''tell the time of day… check where the sun sits… work out the right direction'' 的转述。"},{"q":"Why does the writer call the discovery worrying as well as amazing?","answer":"A","options":["Because monarch numbers have fallen very fast lately.","Because the butterflies fly too slowly.","Because the forests are too warm.","Because no one believes the professor."],"explanation":"末句 ''the number of monarchs has dropped sharply'' 的转述。"}]'::jsonb, '[{"word":"monarch","cn":"黑脉金斑蝶"},{"word":"professor","cn":"教授"},{"word":"direction","cn":"方向"}]'::jsonb, 2, 'required1', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Why Animals Migrate', 'Many animals do not stay in one place all year round. At certain times, they move from one area to another, and this regular movement is called migration. There are several reasons why they do this. The most common one is food: when winter comes and food becomes hard to find, animals travel to places where there is still enough to eat. Some move in order to seek a partner and raise their young in a safer area. Others simply follow the warmer weather. Birds, fish, insects and even some large sea animals all make such journeys. The Atlantic salmon, for example, swims back up the very river where it was born, while certain whales travel thousands of kilometres across the ocean each year. These trips are long and full of danger, but the animals that complete them give their young a far better chance to survive.', 'Into the Wild', 147, '[{"q":"What does the word ''migration'' mean in the passage?","answer":"B","options":["Staying in one place all year.","When animals move regularly between different areas.","Sleeping through the whole winter.","Building a nest in a tree."],"explanation":"原文 ''this regular movement is called migration'' 的转述。"},{"q":"According to the text, what is the most common reason for migration?","answer":"C","options":["The wish to be famous.","A dislike of other animals.","The search for food.","The need for exercise."],"explanation":"中段 ''The most common one is food'' 的转述。"},{"q":"What does completing the journey give the animals?","answer":"D","options":["A longer sleep.","A new colour.","A chance to forget the way home.","A better chance for their young to live."],"explanation":"末句 ''give their young a far better chance to survive'' 的转述。"}]'::jsonb, '[{"word":"migration","cn":"迁徙"},{"word":"seek","cn":"寻找"},{"word":"survive","cn":"存活"}]'::jsonb, 2, 'required1', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'An Encounter with a Bear', 'Last spring, while taking photos in a national park, I followed a path that led me through a dark forest. When I stepped out of the trees, the view took my breath away. An eagle flew over the snow-capped mountains, which were mirrored in the still lake below. As I was concentrating on this scene, I suddenly felt that I was being watched. Slowly, with my camera still held to my eye, I turned and froze. Only a few metres away stood a large bear, water dropping from its thick brown hair as it stared straight back at me. Time seemed to stop while we both waited to see who would move first. My legs began to shake, but somehow I forced my finger to press the button. A moment later, the bear turned and ran back into the trees. When I recovered, I realised that my most frightening yet magical experience was now saved forever in a single picture.', 'Into the Wild', 160, '[{"q":"What did the writer feel when first stepping out of the trees?","answer":"A","options":["Greatly impressed by the beautiful scene.","Bored by the empty view.","Afraid of getting lost.","Tired and ready to leave."],"explanation":"原文 ''the view took my breath away'' 的转述。"},{"q":"How did the writer react on seeing the bear so close?","answer":"B","options":["He ran away at once.","He froze and could not move at first.","He shouted loudly for help.","He climbed up a tall tree."],"explanation":"原文 ''I turned and froze… My legs began to shake'' 的转述。"},{"q":"What does the writer keep from that day?","answer":"C","options":["A wound on his arm.","A friendship with the bear.","A single photo of the whole experience.","A fear of all forests."],"explanation":"末句 ''saved forever in a single picture'' 的转述。"}]'::jsonb, '[{"word":"concentrate","cn":"专注"},{"word":"freeze","cn":"呆住"},{"word":"stare","cn":"凝视"}]'::jsonb, 2, 'required1', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Pandas Far from Home', 'In the spring of 2017, two giant pandas from China arrived at a zoo in the Netherlands. Workers had spent months getting ready for them, and the animals were welcomed into a Chinese-style home built specially for their stay. A few weeks later, after everything was complete, the day finally came for the pandas to meet their fans. People were very excited, partly because this zoo was the only place in the whole country where the public could see pandas, and partly because the last time pandas had lived there was thirty years before. Of course, another reason for the great excitement was simply that pandas are so lovely to look at. The visit was about more than fun, though. It was also a sign of warm feelings between two countries, and it gave local children a chance to learn about a rare creature they might never see in the wild.', 'Into the Wild', 151, '[{"q":"Why was the day the pandas met their fans special?","answer":"D","options":["The pandas had been born at that very zoo.","The zoo was about to close down.","The pandas could already speak Dutch.","It was the country''s only panda zoo, and none had been seen there for thirty years."],"explanation":"中段 ''the only place… the last time pandas had lived there was thirty years before'' 的转述。"},{"q":"Besides being exciting, what did the visit stand for?","answer":"A","options":["Friendly feelings between two countries.","A new kind of food.","A bigger zoo ticket price.","The end of panda research."],"explanation":"末段 ''a sign of warm feelings between two countries'' 的转述。"},{"q":"What chance did the visit give local children?","answer":"B","options":["A chance to feed wild bears.","An up-close look at an unusual creature.","A chance to travel to China.","A chance to keep a panda at home."],"explanation":"末句 ''a chance to learn about a rare creature'' 的转述。"}]'::jsonb, '[{"word":"complete","cn":"完成的"},{"word":"creature","cn":"生物"},{"word":"rare","cn":"稀有的"}]'::jsonb, 2, 'required1', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Should Animals Live in Zoos?', 'People often argue about whether wild animals should be kept in zoos. Those who are for zoos say that a good zoo can help protect animals that are in danger. They also believe zoos are a fine way to teach the public, because they let visitors see and learn about animals in surroundings that are made to feel like the wild. Those who are against zoos see things differently. They say that no zoo can truly offer an animal the home that nature gives it. They also worry that zoo animals may lose their natural skills and be unable to live on their own if they are ever set free again. Some even feel that zoos are really built for people rather than for the animals inside them. Both sides care about the same thing, the well-being of the animals, yet they reach very different answers, which is exactly why the debate has gone on for so long.', 'Into the Wild', 158, '[{"q":"What is one point made by people who support zoos?","answer":"C","options":["Zoos should charge much higher prices.","Animals dislike being watched.","A well-run zoo can keep endangered animals safe.","Zoos should only keep insects."],"explanation":"原文 ''a good zoo can help protect animals that are in danger'' 的转述。"},{"q":"Why do some people worry about keeping animals in zoos?","answer":"D","options":["The animals eat too much.","The zoos are always empty.","The animals learn to speak.","The animals may lose the skills needed to live in the wild."],"explanation":"中段 ''may lose their natural skills and be unable to live on their own'' 的转述。"},{"q":"Why has the debate lasted so long, according to the writer?","answer":"A","options":["Because the two sides share one concern yet disagree on the answer.","Because nobody really cares.","Because zoos are too expensive.","Because there are no wild animals left."],"explanation":"末句 ''both sides care about the same thing… reach very different answers'' 的转述。"}]'::jsonb, '[{"word":"argue","cn":"争论"},{"word":"surroundings","cn":"环境"},{"word":"debate","cn":"辩论"}]'::jsonb, 2, 'required1', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Red-crowned Crane', 'The red-crowned crane is one of the largest cranes in the world, standing about one and a half metres tall. Its feathers are as white as snow, apart from some black ones on its face, neck and wings. Its most special feature, which gives the bird its name, is the bright red skin on the top of its head. This crane can be found in China, Russia, Mongolia, Japan and Korea. In China, it spends the warmer months in the rivers and wetlands of the north-east. When the cold weather arrives, it migrates to the central and eastern parts of the country, where the winter is gentler. Its meals include fish, snails and water plants. To many Chinese people, the red-crowned crane is far more than a beautiful bird, for it has long been a symbol of long life and good luck in their culture.', 'Into the Wild', 145, '[{"q":"What gives the red-crowned crane its name?","answer":"B","options":["Its long white neck.","The bright red patch crowning its head.","The black feathers on its wings.","Its loud morning call."],"explanation":"原文 ''the bright red skin on the top of its head'' 的转述。"},{"q":"Where does the crane go when winter arrives in China?","answer":"C","options":["It flies far across the ocean.","It stays in the frozen north-east.","It moves to the milder central and eastern areas.","It hides inside caves."],"explanation":"中段 ''migrates to the central and eastern parts… winter is gentler'' 的转述。"},{"q":"What does the bird mean in Chinese culture?","answer":"D","options":["Hard work and study.","Bad weather ahead.","A long journey home.","Good fortune and a long life."],"explanation":"末句 ''a symbol of long life and good luck'' 的转述。"}]'::jsonb, '[{"word":"feature","cn":"特征"},{"word":"migrate","cn":"迁徙"},{"word":"symbol","cn":"象征"}]'::jsonb, 2, 'required1', 'U5', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U5', 'A Wildlife Photographer''s Day', 'Being a wildlife photographer is not an easy job. To get a good photo, I often have to (1)____ the elements, working outside in the wind and the rain. Early in the morning I follow a quiet (2)____ into the forest and wait. Sometimes I have to (3)____ very still for hours, holding my camera and watching. When a wild animal finally appears, I try to stay (4)____ so that I do not frighten it away. I must (5)____ on the animal and forget everything else around me. The hardest moment comes when I press the (6)____ at exactly the right time. One single (7)____ can show the beauty of a creature that most people will never (8)____ in the wild. After a long day, I am tired but happy. Each photo is a small (9)____ of a world that we should all learn to (10)____.', 146, 2, '[{"q":"1","answer":"A","options":["brave","buy","sell","lose"],"explanation":"brave the elements 不顾恶劣天气。"},{"q":"2","answer":"B","options":["price","path","noise","season"],"explanation":"a quiet path 一条安静的小路。"},{"q":"3","answer":"C","options":["throw","drop","stay","spend"],"explanation":"stay still 保持不动。"},{"q":"4","answer":"D","options":["loud","angry","busy","calm"],"explanation":"stay calm 保持镇静。"},{"q":"5","answer":"A","options":["concentrate","forget","shout","sleep"],"explanation":"concentrate on 专注于。"},{"q":"6","answer":"B","options":["window","button","garden","market"],"explanation":"press the button 按下按钮。"},{"q":"7","answer":"C","options":["price","noise","image","ticket"],"explanation":"a single image 一张图像。"},{"q":"8","answer":"D","options":["eat","buy","sell","see"],"explanation":"see in the wild 在野外看到。"},{"q":"9","answer":"A","options":["record","machine","shop","city"],"explanation":"a record of 对……的记录。"},{"q":"10","answer":"B","options":["destroy","respect","waste","forget"],"explanation":"respect 尊重(自然世界)。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U5', 'Saving the Monarch Butterfly', 'The monarch butterfly is in serious (1)____. In just a few years, its numbers have fallen by as much as ninety per (2)____. The main (3)____ for this is human activity. In many of the places (4)____ the butterfly can be found, people are (5)____ the natural environment. They cut down trees and use (6)____ that kill the very plants the caterpillars need to (7)____. Luckily, scientists have helped more people become (8)____ of the problem. Groups now work together to record the butterfly''s (9)____ and to make sure there are enough plants for it to feed on. If this careful work goes on, there may come a time (10)____ the number of monarchs starts to rise once again.', 119, 2, '[{"q":"1","answer":"C","options":["music","price","trouble","game"],"explanation":"in serious trouble 陷入严重困境。"},{"q":"2","answer":"D","options":["hour","metre","minute","cent"],"explanation":"per cent 百分之……。"},{"q":"3","answer":"A","options":["reason","price","noise","garden"],"explanation":"the main reason 主要原因。"},{"q":"4","answer":"B","options":["why","where","when","what"],"explanation":"the places where 地点先行词用 where。"},{"q":"5","answer":"C","options":["building","cleaning","destroying","saving"],"explanation":"destroy the environment 破坏环境。"},{"q":"6","answer":"D","options":["songs","tickets","stories","chemicals"],"explanation":"chemicals 化学品。"},{"q":"7","answer":"A","options":["eat","sell","hide","buy"],"explanation":"plants the caterpillars need to eat 毛虫要吃的植物。"},{"q":"8","answer":"B","options":["afraid","aware","tired","proud"],"explanation":"become aware of 意识到。"},{"q":"9","answer":"C","options":["price","noise","migration","weather"],"explanation":"record its migration 记录其迁徙。"},{"q":"10","answer":"D","options":["which","where","why","when"],"explanation":"a time when 时间先行词用 when。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U5', 'A Walk in the National Park', 'Last summer my family visited a national park (1)____ a wide variety of wild animals live. As the world''s first park of its kind, it is (2)____ for its beautiful lakes and forests. On our first morning, we got up early and followed a (3)____ that took us deep into the trees. The air was fresh, and everything was so quiet that we hardly dared to (4)____. Suddenly, my sister pointed at the sky. High above the mountains, a huge bird was flying in slow circles. "Look, an (5)____!" she said softly. We all stopped and (6)____ at it until it disappeared. Later, beside a still (7)____, we saw a family of deer come down to drink. My father reminded us to keep our (8)____ low so that we would not (9)____ the animals away. That day taught me that nature is a world (10)____ every creature has its own quiet place.', 152, 2, '[{"q":"1","answer":"A","options":["where","when","why","which"],"explanation":"a park where 地点先行词用 where。"},{"q":"2","answer":"B","options":["afraid","famous","angry","sorry"],"explanation":"be famous for 因……闻名。"},{"q":"3","answer":"C","options":["price","noise","path","ticket"],"explanation":"follow a path 沿着小路。"},{"q":"4","answer":"D","options":["sell","buy","throw","breathe"],"explanation":"hardly dared to breathe 几乎不敢呼吸。"},{"q":"5","answer":"A","options":["eagle","price","market","garden"],"explanation":"an eagle 一只鹰。"},{"q":"6","answer":"B","options":["shouted","stared","slept","sold"],"explanation":"stare at 凝视。"},{"q":"7","answer":"C","options":["price","noise","lake","shop"],"explanation":"a still lake 平静的湖。"},{"q":"8","answer":"D","options":["money","books","shoes","voices"],"explanation":"keep our voices low 压低声音。"},{"q":"9","answer":"A","options":["frighten","help","feed","carry"],"explanation":"frighten the animals away 把动物吓跑。"},{"q":"10","answer":"B","options":["when","where","why","what"],"explanation":"a world where 抽象地点用 where。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U5', 'The Amazing Eagle', 'The eagle is one of the most (1)____ birds in the world. With its sharp eyes, it can (2)____ a small animal moving far below on the ground. When it sees something to eat, it drops from the sky at an (3)____ speed. Eagles usually build their large nests high on cliffs or in tall (4)____, in places (5)____ few other animals can reach. There they raise their young in (6)____. A young eagle stays in the nest until the day (7)____ it is finally strong enough to fly. Sadly, in some areas the number of eagles has begun to (8)____, because people are destroying the wild land they need. If we want these (9)____ birds to survive, we must protect the quiet, high places (10)____ they make their homes.', 130, 2, '[{"q":"1","answer":"C","options":["boring","ordinary","amazing","empty"],"explanation":"amazing 了不起的。"},{"q":"2","answer":"D","options":["eat","buy","sell","see"],"explanation":"can see 能看见。"},{"q":"3","answer":"A","options":["amazing","empty","easy","early"],"explanation":"an amazing speed 惊人的速度。"},{"q":"4","answer":"B","options":["prices","trees","songs","shops"],"explanation":"in tall trees 在高高的树上。"},{"q":"5","answer":"C","options":["when","why","where","which"],"explanation":"places where 地点先行词用 where。"},{"q":"6","answer":"D","options":["danger","trouble","noise","safety"],"explanation":"in safety 安全地。"},{"q":"7","answer":"A","options":["when","which","where","why"],"explanation":"the day when 时间先行词用 when。"},{"q":"8","answer":"B","options":["rise","fall","grow","win"],"explanation":"the number has begun to fall 数量开始下降。"},{"q":"9","answer":"C","options":["boring","ordinary","amazing","empty"],"explanation":"these amazing birds 这些了不起的鸟。"},{"q":"10","answer":"D","options":["when","why","what","where"],"explanation":"places where 地点先行词用 where。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U5', 'Helping the Red Panda', 'The red panda is a small, lovely (1)____ that lives in the mountain forests of Asia. Sadly, it is now in (2)____, and its numbers keep falling. One main (3)____ why this is happening is the loss of its forest home. As people cut down trees, the red panda has fewer and fewer places (4)____ it can find food and feel safe. Local (5)____ have now set up reserves to protect the animal. In these protected areas, the forests are not (6)____, and the pandas can live in peace. Workers also (7)____ the plants the pandas like to eat, so that there is always enough food. Scientists carefully (8)____ how many red pandas are left, and they share the (9)____ with people around the world. With this kind of help, there is real hope that the red panda will (10)____ for many years to come.', 145, 2, '[{"q":"1","answer":"A","options":["creature","price","machine","market"],"explanation":"a lovely creature 可爱的生物。"},{"q":"2","answer":"B","options":["safety","danger","music","order"],"explanation":"in danger 处于危险中。"},{"q":"3","answer":"C","options":["price","noise","reason","garden"],"explanation":"the main reason why 主要原因。"},{"q":"4","answer":"D","options":["when","why","what","where"],"explanation":"places where 地点先行词用 where。"},{"q":"5","answer":"A","options":["authorities","songs","tickets","prices"],"explanation":"local authorities 当地管理机构。"},{"q":"6","answer":"B","options":["cleaned","destroyed","opened","saved"],"explanation":"are not destroyed 没有被破坏。"},{"q":"7","answer":"C","options":["sell","hide","grow","throw"],"explanation":"grow the plants 种植植物。"},{"q":"8","answer":"D","options":["forget","lose","waste","record"],"explanation":"record how many 记录数量。"},{"q":"9","answer":"A","options":["results","price","noise","weather"],"explanation":"share the results 分享结果。"},{"q":"10","answer":"B","options":["stop","survive","fail","disappear"],"explanation":"will survive 将存活下来。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U5', 'Animals and Their Homes', 'Every wild animal needs a place it can call (1)____. For some, home is a warm cave (2)____ they sleep through the cold winter. For others, it is a (3)____ deep in the forest, far from any road. Fish need clean rivers and lakes, while birds need tall trees (4)____ they can build their nests in safety. When these natural homes are (5)____, the animals lose far more than just a place to rest. They may no longer find enough (6)____ to eat, and their young may not (7)____. This is the real (8)____ why protecting wild places matters so much. By keeping forests, rivers and wetlands clean and safe, we make sure that every (9)____ still has somewhere to live. After (10)____, it is we who are only visitors to their world.', 133, 2, '[{"q":"1","answer":"C","options":["price","noise","home","shop"],"explanation":"call home 称之为家。"},{"q":"2","answer":"D","options":["which","when","why","where"],"explanation":"a cave where 地点先行词用 where。"},{"q":"3","answer":"A","options":["valley","price","market","ticket"],"explanation":"a valley 山谷(地点)。"},{"q":"4","answer":"B","options":["why","where","when","what"],"explanation":"tall trees where 地点先行词用 where。"},{"q":"5","answer":"C","options":["built","cleaned","destroyed","opened"],"explanation":"homes are destroyed 家被毁。"},{"q":"6","answer":"D","options":["money","books","shoes","food"],"explanation":"enough food 足够的食物。"},{"q":"7","answer":"A","options":["survive","sell","buy","throw"],"explanation":"young may not survive 幼崽可能活不下来。"},{"q":"8","answer":"B","options":["price","reason","noise","weather"],"explanation":"the reason why 原因。"},{"q":"9","answer":"C","options":["machine","shop","creature","city"],"explanation":"every creature 每个生物。"},{"q":"10","answer":"D","options":["school","lunch","class","all"],"explanation":"after all 毕竟。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·对话 Planning a Wildlife Trip', '外研社版必修第一册 U5 · dialogue', 3, 'Lily: Where do you want to go this weekend, Tom?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·短文 Why Animals Travel', '外研社版必修第一册 U5 · passage', 2, 'Many animals do not spend the whole year in one place.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·对话 The Zoo Debate', '外研社版必修第一册 U5 · dialogue', 3, 'Mia: I think zoos are good because they protect animals in danger.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·短文 The Monarch Butterfly', '外研社版必修第一册 U5 · passage', 2, 'Each autumn, monarch butterflies fly thousands of kilometres south.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·对话 Advice for Watching Bears', '外研社版必修第一册 U5 · dialogue', 3, 'Ben: I''m going to photograph bears next week. Any advice?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U5 听力·短文 Respecting Wild Animals', '外研社版必修第一册 U5 · passage', 2, 'Wild animals are not pets, and they belong in nature.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write an Animal Fact File(写一份动物档案)', 'An Animal Fact File', '请用英语写一份约80词的动物档案,介绍一种你喜欢的野生动物。内容包括:① 它长什么样(外貌/独特特征);② 它生活在哪里;③ 它吃什么或它如何迁徙;④ 关于它的一条其他信息(如象征意义或为何需要保护)。注意:用定语从句让句子更连贯。', 'Write an animal fact file (about 80 words) about a wild animal you like. Include: 1) what it looks like (appearance / a special feature); 2) where it lives; 3) what it eats or how it migrates; 4) one piece of other information (such as its symbolic meaning or why it needs protecting). Try to use attributive clauses to link your ideas.', '["外貌/独特特征(It is … tall. / Its unique feature is …)","栖息地(It is found in … / It lives in places where …)","食物或迁徙(Its food includes … / When winter comes, it migrates to …)","其他信息 + 用定语从句连接句子"]'::jsonb, 70, 100, 'The red-crowned crane is one of the largest cranes in the world, standing about 150 cm tall. Its feathers are as white as snow, and its unique feature, which gives the bird its name, is the bright red skin on top of its head. It is found in China, Russia and Japan. In China, it lives in northern wetlands where there is plenty of food, such as fish and water plants. When winter comes, it migrates to milder areas in the east. To Chinese people, this crane is a symbol of long life and good luck.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Its unique feature, which gives the bird its name, is the bright red skin on its head.","It lives in northern wetlands where there is plenty of food.","When winter comes, it migrates to milder areas in the east.","To Chinese people, this crane is a symbol of long life and good luck."]'::jsonb, '[{"wrong":"It lives in wetlands where it is full of food.","correct":"It lives in wetlands where there is plenty of food.","note":"where 引导地点状语从句,后面用 there is,不再加多余主语 it。"},{"wrong":"Winter comes, it migrates to the east.","correct":"When winter comes, it migrates to the east.","note":"两个句子要用连词 When 连接,不能直接逗号相连。"},{"wrong":"Its food include fish and plants.","correct":"Its food includes fish and plants.","note":"主语 food 第三人称单数,动词加 s。"}]'::jsonb, '【动物档案结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required1', 'U5', '{"title":"限制性定语从句·关系副词 when / where / why 速查","intro":"关系副词在从句中作状语(时间/地点/原因),等于「介词+which」。判断口诀:从句缺状语→用关系副词,缺主语/宾语→用关系代词 that/which。","table":{"headers":["关系副词","用法 / 例句 / 等价"],"rows":[["when","时间先行词(day/time/year/season):the day when = on/in which"],["where","地点先行词(place/forest/lake/park):the place where = in/at which"],["why","原因(reason):the reason why = for which"],["介词+which","从句缺主宾、或表达更正式:on which / in which / by which / with which"]]},"specialRules":[{"rule":"从句只缺状语(时间/地点/原因)→ 才用关系副词","mark":"the forest where I took photos(缺地点状语)"},{"rule":"从句缺主语/宾语 → 即使先行词是时间/地点也用 that","mark":"the day that changed my view(缺主语→that)"},{"rule":"the day when = on/in which;the place where = in/at which;the reason why = for which","mark":"等价替换"},{"rule":"介词后只能用 which,不可用 that","mark":"trees on which √ / trees on that ×"}],"why":["关系副词 = 介词 + which,在从句里充当状语,所以从句的主语、宾语都不缺;一旦主语或宾语缺了,就要换成关系代词 that/which。"],"gaokaoPoints":["when/where/why 与 which/that 的判断(看从句缺什么成分);介词+which;语法填空高频。","the way 后的定语从句:用 that / in which / 或省略,但不用 which 单独引导。"],"examVsReal":[{"exam":"the forest where I work（考试/书面）","real":"the forest I work in","note":"考试用 where;口语常省略关系词、把介词放句末"},{"exam":"the reason why the bird left（考试）","real":"the reason the bird left / the reason that the bird left","note":"考试用 why;口语里 why 常被省略或用 that"}]}'::jsonb, 'fltrp');
